                open_count += 1
                if open_count == 1:
                    cluster += char
            elif char == ')':
                open_count -= 1
                if open_count == 0:
                    cluster += char
                    clusters.append(cluster)
                    cluster = ""
            else:
                if open_count > 0:
                    cluster += char

        return clusters

    def remove_spaces(clusters):
        return [cluster.replace(" ", "") for cluster in clusters]

    def separate_clusters(clusters):
        return clusters

    def check_balance(clusters):
        return [cluster for cluster in clusters if cluster.count('(') == cluster.count(')')]

    clusters = extract_clusters(paren_string)
    clusters = remove_spaces(clusters)
    clusters = separate_clusters(clusters)
    balanced_clusters = check_balance(clusters)

    return balanced_clusters

